EventListenerHandler::EventListenerHandler() : AppExecFwk::EventHandler(AppExecFwk::EventRunner::Create())
{
    AddBasicHandlerToMap();
    AddNetworkHandlerToMap();
    AddWorkFuncToMap();
}

